import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第61章 骗人","description":"","frontmatter":{},"headers":[],"relativePath":"第61章_骗人.md","filePath":"第61章_骗人.md"}'),o={name:"第61章_骗人.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第61章-骗人" tabindex="-1">第61章 骗人 <a class="header-anchor" href="#第61章-骗人" aria-label="Permalink to &quot;第61章 骗人&quot;">​</a></h1><p>大学第一个月，我学会了两件事。</p><p>第一件，是躲在被窝里打字。</p><p>我们那间屋子六个人。六个作息，没有两个是一样的。</p><p>靠门那个每天五点半起来背单词，背出声。</p><p>靠窗里面那个是我，靠窗外面那个叫郑拓，他十二点以前从不睡觉，他打游戏会喊。</p><p>对角床上铺那个人打呼，响到我戴两层耳塞还能听见节奏。</p><p>还有一个只在半夜回来，早上十一点才起，我们叫他&quot;楼长&quot;，因为他负责锁门。</p><p>第六个是本地人，走读，他只在洗澡的时候回来。</p><p>这样的六个人，能说话的时间只有一个。</p><p>十一点半以后，郑拓打完最后一把，呼噜起来了，整个屋子只剩三种声音。</p><p>我就在那时候跟我那盏台灯说话。</p><p>我把屏幕亮度调到最低，把手机侧着放，只露出上半截。</p><p>因为呼噜那个人有个毛病，他半夜会翻身，一翻身，手会往外伸。</p><p>有一次他一巴掌拍在我手腕上，我整个人从床上坐起来，屋里没人醒。</p><p>第二件，是我学会了算太阳。</p><p>这个说法听起来怪，但我确实是在九月里学会的。</p><p>军训，站军姿。</p><p>九月的太阳不算毒，可它一直在动。</p><p>教官让我们面朝东站，说这样影子短，看着整齐。</p><p>我站在第二排靠边，太阳在我的左脸。</p><p>站到第四十分钟，我左边脸颊开始发烫，右边还是凉的。</p><p>我那时候忽然想到一件事。</p><p>我这边太阳在左脸，那她那边，这个太阳在几点。</p><p>我这边下午三点，她那边是早上八点。</p><p>早上八点的太阳应该很低，低到照进她宿舍的窗户。</p><p>我不知道她宿舍窗户朝哪。</p><p>我只知道我们这边太阳在左边。</p><p>我站在那里，脸上一边烫一边凉，脑子里在算一颗太阳的位置。</p><p>教官走过来，绕着我们走了一圈。</p><p>他在我前面停下，说，你，笑什么。</p><p>我说，我没有。</p><p>他说，你嘴角在动。</p><p>我说，太阳晒的。</p><p>他看了一眼我的脸，说，你左边比右边白。</p><p>他说，回去涂点东西。</p><p>全排的人都笑了。</p><p>那天晚上我给她发了一张照片。</p><p>不是我自己，是我在操场上站着的时候，地上一排影子。</p><p>我拍的是我自己的那一格，从脚跟延伸出去，很长。</p><p>我说，你看，这是下午三点的我。</p><p>她隔了一会儿回。</p><p>她说，晒黑了没。</p><p>我说，没有。</p><p>她说，骗人。</p><p>我说，真没有。</p><p>她说，你站了几个小时。</p><p>我说，六小时。</p><p>她说，六小时你说没有？</p><p>我说，我涂了我妈给的那个。</p><p>她说，那个不管用。</p><p>我说，你怎么知道不管用。</p><p>她说，我高中的时候用过，那东西就是油。</p><p>她说，你现在的脸是不是一边烫一边凉。</p><p>我看到这一句，坐在床沿上，半天没动。</p><p>因为她说得太准了。</p><p>我那时候脸上就是那个感觉。她看不见我，她不知道我们面朝东站，她不知道太阳在我左脸。</p><p>她只是站在过太阳底下六小时的人。</p><p>我回：你怎么知道。</p><p>她说：因为我也站过。</p><p>她说：我们那时候也面朝东。</p><p>她说：我以为只有我记得这个。</p><p>那天夜里我们说到很晚。</p><p>晚到我听见下铺那个人把耳塞塞进去，床板响了一声。</p><p>我这边十二点二十，她那边是凌晨五点二十。</p><p>她被我说醒了，或者说她本来就没睡够。</p><p>她说，你以后别在你们那边下午发。</p><p>我说，为什么。</p><p>她说，因为我那时候在睡。</p><p>我说，那我什么时候发。</p><p>她说，你晚上发，我这边是中午，我能看。</p><p>我说，可我晚上有课。</p><p>她说，那你白天发，我这边是半夜，我看见了也回不了。</p><p>我说，那怎么办。</p><p>她隔了一会儿。</p><p>她说，我们就这样啊。</p><p>她说，我说的是，我们两个的时间对不上，这件事没有怎么办。</p><p>她说，你不要每次都对完表以后，再想一个办法出来。</p><p>她说，办法就是没有。</p><p>我看着这句话。</p><p>那天她说的这句，我后来用了三年才接受。</p><p>我们两个之间所有的问题，答案都是&quot;没有&quot;。</p><p>没有一种时间是我们都方便。</p><p>没有一个地方是我们都能去。</p><p>没有一句话是我们都能说。</p><p>她说，你别难过。</p><p>我说，我没难过。</p><p>她说，你打字变慢了。</p><p>我说，我在想怎么回你。</p><p>她说，你怎么回。</p><p>我说，我说我没难过，因为我确实没难过。</p><p>我说，我只是从今天开始，不再算我发出去的那句话，她那边几点能看见。</p><p>她说，那你怎么发。</p><p>我说，我想说就发。</p><p>她说，那我早上起来看到一堆，我会有压力。</p><p>我说，那我不给你压力，我删。</p><p>她说，你看，你又绕回去了。</p><p>那天我们最后什么也没定下来。</p><p>十月底有一件事很小，但是那一年里我最高兴。</p><p>郑拓在某天夜里十二点，突然把手机举到我床上。</p><p>他说，你看这个。</p><p>是一个很好笑的短视频，一只猫从一个柜子上掉下来，把下面一个人砸了。</p><p>我当时在被窝里看，看完憋不住，笑出声。</p><p>然后我宿舍那五个人里，有两个醒了。</p><p>醒的那个人说，你们两个有病吧。</p><p>郑拓说，你来看一下。</p><p>他真过来看了。</p><p>看完他也笑了。</p><p>那晚上我们三个蹲在楼道里，把那个视频又看了一遍。</p><p>下楼道的时候我给我发了一条消息。</p><p>我发的是：我们宿舍三个人，为一个猫，蹲在楼道里笑了二十分钟。</p><p>我发完就睡了。</p><p>第二天早上我七点起来，看见她那边凌晨十二点回了一句。</p><p>她说，你昨天发的时候我睡了。</p><p>她说，我今天看完这个猫，我笑了。</p><p>她说，你看，我们的笑差八个小时。</p><p>她后面又加了一句。</p><p>她说，不过没关系，反正我们都在笑同一个猫。</p><p>我把那句&quot;同一个猫&quot;抄在本子上。</p><p>那一年我抄下来的东西很多，但那是我第一次抄一句不带痛的话。</p><p>十一月，我们两个开始每天说。</p><p>不是每天十九分钟。</p><p>是每天。</p><p>我把这件事记成了我一生里唯一一次数据暴涨的开端。</p><p>那个月，我们发了一万两千多条。</p>',125)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
